    // Detecta el cliente por nombre de estación usando las palabras clave del catálogo.
    // No fuerza nada: si no hay coincidencia, regresa null y se captura manual.
    function opsDetectarClientePorNombre(estacion) {
        const texto = String(estacion || "").toLowerCase();
        if (!texto) return null;
        const match = cacheClientes.find(c => (c.palabrasClave || []).some(p => texto.includes(String(p).toLowerCase())));
        return match ? match.id : null;
    }

    // Matriz v2 (oct-2026): el rol "de verdad" sale de Control de acceso. Esta función
    // solo traduce ese rol a las 3 etiquetas viejas que todavía usan algunas pantallas.
    function opsRolActual() {
        const email = String(opsUsuarioActual() || "").toLowerCase().trim();
        if (window.esAdminTotal && window.esAdminTotal(email)) return "administrador";
        const a = opsAccCfg ? opsAccAsignacion() : null;
        if (!a) return opsRolLegado();
        const ro = a.soloLectura || !!(opsAccCfg.roles[a.rol] || {}).soloLectura;
        if (a.rol === "administrador" && !ro) return "administrador";
        if (a.rol === "almacen" && !ro) return "almacen";
        return "consulta";
    }
    function opsRolLegado(correoOpcional) {
        // Puente de compatibilidad con el esquema anterior (admin/almacén/consulta).
        // Desde la Matriz v2 solo se usa para SUGERIR un rol a quien no tiene uno fijo.
        const email = correoOpcional || opsUsuarioActual();
        if (window.esAdminTotal && window.esAdminTotal(email)) return "administrador";
        if (OPS_SOLO_LECTURA.includes((email || "").toLowerCase().trim())) return "consulta";
        if (OPS_ADMINS.includes((email || "").toLowerCase().trim())) return "administrador";
        const almacen = (window.USUARIOS_AREA && window.USUARIOS_AREA["Almacen"]) || [];
        if (almacen.map(e => e.toLowerCase()).includes(email.toLowerCase())) return "almacen";
        return "consulta";
    }

    // Permisos derivados del puesto REAL asignado al usuario en el módulo de Técnicos/Personas
    // (ops_tecnicos.puestoId → ops_puestos.permisos), haciendo match por correo con la sesión
    // actual. Esto es lo que faltaba: antes el catálogo de puestos existía pero nunca se
    // consultaba para decidir permisos de login — solo la lista fija OPS_ADMINS/Almacén.
    function opsPermisosPorPuestoDeCorreo(email) {
        if (!email) return [];
        const correo = String(email).toLowerCase().trim();
        if (OPS_SOLO_LECTURA.includes(correo)) return [];
        const tec = cacheTec.find(t => t.estatus === "activo" && (t.correo || "").toLowerCase().trim() === correo);
        if (!tec || !tec.puestoId) return [];
        if (OPS_FORZAR_TECNICO[correo]) {
            const pt = (cachePuestos.length ? cachePuestos : PUESTOS_SEED).find(p => (p.id && p.id === OPS_FORZAR_TECNICO[correo].puestoId) || p.nombre === OPS_FORZAR_TECNICO[correo].puesto);
            return pt ? (pt.permisos || []) : [];
        }
        // Si cachePuestos aún no cargó (carrera de timing), se cae a PUESTOS_SEED emparejando
        // por nombre de puesto (PUESTOS_SEED no tiene id porque los ids los asigna Firestore).
        const puesto = (cachePuestos.length ? cachePuestos : PUESTOS_SEED)
            .find(p => (p.id && p.id === tec.puestoId) || p.nombre === tec.puesto);
        return puesto ? (puesto.permisos || []) : [];
    }

    function opsPermisosActuales() {
        const email = opsUsuarioActual();
        const rolLegado = opsRolLegado();
        // "administrador" cubre tanto esAdminTotal (admin global del portal) como los
        // OPS_ADMINS (administradores solo de este departamento) — opsRolActual() ya
        // resuelve ambos casos, así que basta con leer su resultado una sola vez.
        if (rolLegado === "administrador") {
            return PUESTOS_SEED.flatMap(p => p.permisos).concat(["admin_operaciones"]); // acceso total
        }
        if (OPS_SOLO_LECTURA.includes((email || "").toLowerCase().trim())) return ["consulta"];
        const basePorRolLegado = rolLegado === "almacen" ? ["gestionar_herramientas", "autorizar_material", "solicitar_material"] : [];
        // Unión: respaldo legado (Almacén) + puesto real asignado al correo actual. Así cualquier
        // usuario con un puesto que incluya el permiso lo tiene, sin depender de listas fijas en código.
        return [...new Set([...basePorRolLegado, ...opsPermisosPorPuestoDeCorreo(email), "consulta"])];
    }

    // Reglas anteriores (listas fijas + puesto). Siguen mandando para quien NO tiene
    // un rol asignado en "Control de acceso" — nadie gana ni pierde acceso por el cambio.
    function opsPuedeHacerLegado(accion) {
        return opsPermisosActuales().includes(accion) || opsPermisosActuales().includes("admin_operaciones");
    }

    // ═══════════════ CONTROL DE ACCESO — matriz de permisos (oct-2026) ═══════════════
    // Una sola fuente: doc ops_config_permisos/general (va a Supabase por el puente).
    //   roles:    { idRol: { nombre, matriz: { seccion: ["ver","editar","eliminar","aprobar","contacto"] } } }
    //   usuarios: { correo: { rol: idRol, soloLectura: bool } }
    //   dinero:   [correos] → únicos que ven precio, costo, utilidad y comisiones
    // Solo los admins del portal (esAdminTotal) editan esto; todo cambio va a ops_auditoria.
    const COL_CONFIG_PERMISOS = "ops_config_permisos";
    const OPS_ACC_SECCIONES = [
        ["calendario", "Calendario"], ["servicios", "Servicios"], ["folios", "Folios"], ["clientes", "Clientes"],
        ["solicitudes", "Solicitudes"], ["dashboard", "Herramientas"], ["guardias", "Guardias"], ["vencimientos", "Vencimientos"],
        ["viaticos", "Viáticos"], ["alertas", "Alertas"], ["garantias", "Garantías"], ["polizas", "Pólizas (próximamente)"],
        ["tecnicos", "Técnicos"], ["externos", "Externos"], ["permisos", "Permisos y vacaciones"], ["movimientos", "Movimientos"], ["resumen", "Resumen"],
    ];
    const OPS_ACC_ACCIONES = [["ver", "Ver"], ["crear", "Crear"], ["editar", "Editar"], ["eliminar", "Eliminar"], ["aprobar", "Aprobar"], ["contacto", "Ver contacto"], ["dinero", "Ver dinero"]];
    // Pestañas que no son sección propia de la matriz: se rigen por otra sección.
    const OPS_ACC_ALIAS = { gestionados: "calendario", revision: "folios" };
    const OPS_ACC_VERSION = 2;
    const OPS_ACC_DINERO_SEED = [
        "clientes@tecnocontrol.com.mx", "magali@tecnocontrol.com.mx", "m.delao@tecnocontrol.com.mx", "p.pinedo@tecnocontrol.com.mx",
        "mercadotecnia@tecnocontrol.com.mx", "mercadotecniatecnocontrol@gmail.com", "rh@tecnocontrol.com.mx", "c.acosta@tecnocontrol.com.mx",
    ];
    function opsAccMatrizTodas(acciones, excepto) {
        const m = {};
        OPS_ACC_SECCIONES.forEach(([s]) => { if (!(excepto || []).includes(s)) m[s] = acciones.slice(); });
        return m;
    }
    function opsAccRolesSeed() {
        const almacen = opsAccMatrizTodas(["ver"]);
        ["dashboard", "solicitudes", "movimientos", "garantias"].forEach(s => { almacen[s] = ["ver", "crear", "editar"]; });
        almacen.solicitudes.push("aprobar");
        const pagos = opsAccMatrizTodas(["ver", "contacto"]);
        pagos.viaticos = ["ver", "contacto", "aprobar"];
        return {
            administrador: { nombre: "Administrador de Operaciones", matriz: opsAccMatrizTodas(["ver", "crear", "editar", "eliminar", "aprobar", "contacto"]) },
            coordinador: { nombre: "Coordinador", matriz: opsAccMatrizTodas(["ver", "crear", "editar", "aprobar", "contacto"]) },
            almacen: { nombre: "Almacén", matriz: almacen },
            tecnico: { nombre: "Técnico", matriz: { calendario: ["ver", "contacto"], servicios: ["ver", "contacto"], folios: ["ver", "contacto"] } },
            consulta_contacto: { nombre: "Consulta con contacto", matriz: opsAccMatrizTodas(["ver", "contacto"]) },
            pagos: { nombre: "Pagos (consulta + aprueba viáticos)", matriz: pagos },
            consulta_basica: { nombre: "Consulta básica", matriz: opsAccMatrizTodas(["ver"]) },
            // 19-oct-2026: VH Verificaciones solo ve SU calendario (servicios de VH y los técnicos que van),
            // con datos del cliente; sin precios, comisiones ni viáticos, y sin poder cambiar nada.
            consulta_vh: { nombre: "Consulta VH (solo calendario de VH)", soloLectura: true, filtroEmpresa: "VH Verificaciones", matriz: { calendario: ["ver", "contacto"] } },
        };
    }
    function opsAccUsuariosSeed() {
        const u = {};
        ["clientes@tecnocontrol.com.mx", "magali@tecnocontrol.com.mx"].forEach(c => { u[c] = { rol: "administrador", soloLectura: false }; });
        ["gestoria@tecnocontrol.com.mx", "gestoria1@tecnocontrol.com.mx", "gestoria2@tecnocontrol.com.mx", "gestoria3@tecnocontrol.com.mx",
            "gestoria4@tecnocontrol.com.mx", "gestoria5@tecnocontrol.com.mx", "d.gutierrez@tecnocontrol.com.mx", "calidad@tecnocontrol.com.mx",
            "contabilidad@tecnocontrol.com.mx", "compras@tecnocontrol.com.mx", "aux.compras@tecnocontrol.com.mx"]
            .forEach(c => { u[c] = { rol: "consulta_contacto", soloLectura: true }; });
        u["pagos@tecnocontrol.com.mx"] = { rol: "pagos", soloLectura: false };
        return u;
    }
    // Avisos con voz por tipo de servicio (15-oct-2026, a petición de Calidad/Jaqueline y JOMAR/Idaly):
    // quién recibe alerta (voz + sonido + aviso en pantalla) cuando se programa o se mueve un servicio.
    const OPS_AVISO_TIPOS = [
        ["scfi", "Servicios SCFI (NOM-005-SCFI)"], ["inspeccion", "Todas las visitas de inspección (Gestoría)"],
        ["anexo", "Anexo 21 y 22"], ["asea", "ASEA"], ["calidad_petroliferos", "Calidad de los petrolíferos"],
        ["laboratorio", "Laboratorio"], ["todos", "Todos los servicios"],
    ];
    const OPS_AVISOS_SEED = [{ correo: "calidad@tecnocontrol.com.mx", tipo: "scfi", voz: true }];
    function opsAvisoTipoNombre(t) { return (OPS_AVISO_TIPOS.find(x => x[0] === t) || [t, t])[1]; }
    function opsAccCfgFabrica() {
        return { roles: opsAccRolesSeed(), usuarios: opsAccUsuariosSeed(), dinero: OPS_ACC_DINERO_SEED.slice(), rolPorDefecto: "consulta_basica", version: OPS_ACC_VERSION, avisos: OPS_AVISOS_SEED.map(x => ({ ...x })) };
    }
    // Matriz v2: (1) "Crear" se separa de "Editar" — quien podía editar conserva crear;
    // (2) las listas fijas del código (OPS_ADMINS, OPS_SOLO_LECTURA) pasan a la matriz;
    // (3) se fija el rol por defecto para quien no tenga rol. Regresa la lista de cambios.
    function opsAccNormalizarV2(cfg) {
        const cambios = [];
        if (!cfg.roles || typeof cfg.roles !== "object") cfg.roles = {};
        if (!cfg.usuarios || typeof cfg.usuarios !== "object") cfg.usuarios = {};
        if (!Array.isArray(cfg.dinero)) cfg.dinero = OPS_ACC_DINERO_SEED.slice();
        if ((cfg.version || 1) < 2) {
            Object.values(cfg.roles).forEach(r => {
                Object.keys(r.matriz || {}).forEach(sec => {
                    const m = r.matriz[sec];
                    if (Array.isArray(m) && m.includes("editar") && !m.includes("crear")) m.push("crear");
                });
            });
            cambios.push("Crear separado de Editar (quien editaba conserva crear)");
            OPS_ADMINS.forEach(c => {
                if (cfg.usuarios[c] || !cfg.roles.administrador) return;
                cfg.usuarios[c] = { rol: "administrador", soloLectura: false };
                cambios.push(c + " → Administrador de Operaciones");
            });
            // Personas de la lista de fábrica que se agregaron después de guardar la matriz
            // (ej. gestoria1@…gestoria5@): por esto gestoria3 no veía los contactos.
            Object.entries(opsAccUsuariosSeed()).forEach(([c, u]) => {
                if (cfg.usuarios[c] || !cfg.roles[u.rol]) return;
                cfg.usuarios[c] = { rol: u.rol, soloLectura: !!u.soloLectura };
                cambios.push(c + " → " + cfg.roles[u.rol].nombre + (u.soloLectura ? " · Solo lectura" : ""));
            });
            OPS_SOLO_LECTURA.forEach(c => {
                if (cfg.usuarios[c]) return;
                const rol = c === "pagos@tecnocontrol.com.mx" && cfg.roles.pagos ? "pagos" : "consulta_contacto";
                if (!cfg.roles[rol]) return;
                cfg.usuarios[c] = { rol, soloLectura: rol !== "pagos" };
                cambios.push(c + " → " + cfg.roles[rol].nombre + (rol !== "pagos" ? " · Solo lectura" : ""));
            });
            cfg.version = OPS_ACC_VERSION;
        }
        if (!Array.isArray(cfg.avisos)) {
            cfg.avisos = OPS_AVISOS_SEED.map(x => ({ ...x }));
            cambios.push("Avisos con voz: " + cfg.avisos.map(a => a.correo + " → " + opsAvisoTipoNombre(a.tipo)).join(", "));
        }
        if (!cfg.rolPorDefecto || !cfg.roles[cfg.rolPorDefecto]) {
            cfg.rolPorDefecto = cfg.roles.consulta_basica ? "consulta_basica" : (Object.keys(cfg.roles)[0] || "");
            cambios.push("Rol por defecto: " + ((cfg.roles[cfg.rolPorDefecto] || {}).nombre || "—"));
        }
        return cambios;
    }
    let opsAccCfg = null;          // null = todavía no carga → todos usan las reglas anteriores
    let opsAccRespaldo = false;    // true = no se pudo leer la base; se usa la matriz de fábrica sin poder editarla
    let opsAccVista = "roles";     // pestaña interna de la pantalla: roles | usuarios | dinero | bitacora
    let opsAccRolSel = "consulta_contacto";
    let opsAccBitacora = null;

    async function opsAccCargar() {
        opsAccRespaldo = false;
        try {
            const { db, fs } = await opsGetFB();
            const ref = fs.doc(db, COL_CONFIG_PERMISOS, "general");
            const snap = await Promise.race([fs.getDoc(ref), new Promise((_, ko) => setTimeout(() => ko(new Error("tiempo agotado")), 8000))]);
            if (snap.exists() && snap.data().roles) {
                const d = snap.data();
                if (d.roles && !d.roles.consulta_vh) d.roles.consulta_vh = opsAccRolesSeed().consulta_vh;
                opsAccCfg = { roles: d.roles || {}, usuarios: d.usuarios || {}, dinero: Array.isArray(d.dinero) ? d.dinero : OPS_ACC_DINERO_SEED.slice(), rolPorDefecto: d.rolPorDefecto || "", version: d.version || 1, avisos: d.avisos, empresasServicio: d.empresasServicio || {} };
                const cambios = opsAccNormalizarV2(opsAccCfg);
                // Solo un admin del portal guarda la actualización (queda en la bitácora).
                if (cambios.length && window.esAdminTotal && window.esAdminTotal(opsUsuarioActual())) {
                    try {
                        await fs.setDoc(ref, { ...opsAccCfg, actualizado: opsFechaHora(), actualizadoPor: opsUsuarioActual() });
                        await opsAuditar("permisos", "general", "actualizacion_matriz_v2", null, cambios.join(" | "));
                    } catch (e2) { console.warn("[operaciones.js] no se pudo guardar la Matriz v2:", e2.message); }
                }
            } else {
                // Primera vez: se siembra con las reglas que ya existían (mismo resultado que hoy)
                opsAccCfg = opsAccCfgFabrica();
                if (window.esAdminTotal && window.esAdminTotal(opsUsuarioActual())) {
                    await fs.setDoc(ref, { ...opsAccCfg, actualizado: opsFechaHora(), actualizadoPor: opsUsuarioActual() });
                    await opsAuditar("permisos", "general", "configuracion_inicial", null, "Matriz sembrada con las reglas anteriores");
                }
            }
        } catch (e) {
            // Respaldo: mismas reglas sembradas, en memoria y SIN permitir editar (para no
            // sobrescribir la configuración real con la de fábrica si fue solo un fallo de red).
            console.warn("[operaciones.js] Control de acceso no cargó; se usa el respaldo de fábrica:", e.message);
            opsAccCfg = opsAccCfgFabrica();
            opsAccRespaldo = true;
        }
    }
    function opsAccCorreo() { return String(opsUsuarioActual() || "").toLowerCase().trim(); }
    function opsAccEsAdminPortal() { return !!(window.esAdminTotal && window.esAdminTotal(opsAccCorreo())); }
    // Rol que le toca a un correo cuando NO tiene uno fijo en la matriz: el equivalente
    // exacto de las reglas anteriores (listas fijas, puesto, Almacén) o el rol por defecto.
    // Así nadie gana ni pierde acceso, y todo se decide con UNA sola matriz.
    function opsAccSugerido(correo) {
        if (!opsAccCfg) return null;
        const c = String(correo || "").toLowerCase().trim();
        const roles = opsAccCfg.roles;
        const ok = id => (roles[id] ? id : null);
        let rol = null, soloLectura = false, motivo = "", revisar = false;
        // Cualquier correo de VH (dominio) entra con el calendario de VH, solo lectura (19-oct-2026).
        if (/@vhverifica(ciones)?\.com(\.mx)?$/.test(c) && roles.consulta_vh) {
            return { rol: "consulta_vh", soloLectura: true, sugerido: true, motivo: "Correo de VH Verificaciones", revisar: false };
        }
        if (OPS_ADMINS.includes(c)) { rol = ok("administrador"); motivo = "Admin de Operaciones (lista anterior)"; }
        else if (OPS_SOLO_LECTURA.includes(c)) {
            rol = c === "pagos@tecnocontrol.com.mx" && roles.pagos ? "pagos" : ok("consulta_contacto");
            soloLectura = rol !== "pagos"; motivo = "Solo lectura (lista anterior)";
        } else {
            let perm = [];
            try { perm = opsPermisosPorPuestoDeCorreo(c); } catch (e) { perm = []; }
            const almacen = ((window.USUARIOS_AREA && window.USUARIOS_AREA["Almacen"]) || []).map(e => String(e).toLowerCase()).includes(c);
            if (perm.includes("admin_operaciones")) { rol = ok("administrador"); motivo = "Puesto: Gerente de Operaciones"; }
            else if (perm.includes("gestionar_herramientas") || perm.includes("gestionar_tecnicos") || perm.includes("autorizar_material") || almacen) {
                rol = ok("coordinador"); motivo = almacen ? "Almacén (lista anterior)" : "Puesto con permisos de edición";
            } else if (perm.includes("solicitar_material")) { motivo = "Puesto con 'solicitar material': revisa su rol"; revisar = true; }
        }
        if (!rol) { rol = opsAccCfg.rolPorDefecto; if (!motivo) motivo = "Rol por defecto"; }
        if (!roles[rol]) return null;
        return { rol, soloLectura, sugerido: true, motivo, revisar };
    }
    // Rol del usuario actual: el fijo de la matriz o, si no tiene, el sugerido.
    // null solo para admins del portal (acceso total) o si la matriz no ha cargado.
    function opsAccAsignacion() {
        if (!opsAccCfg || opsAccEsAdminPortal()) return null;
        const a = opsAccCfg.usuarios[opsAccCorreo()];
        if (a && opsAccCfg.roles[a.rol]) return a;
        return opsAccSugerido(opsAccCorreo());
    }
    function opsAccSeccion(seccion) { return OPS_ACC_ALIAS[seccion] || seccion; }
    // Empresa a la que está limitado el usuario (ej. VH): solo ve servicios de esa empresa.
    function opsAccFiltroEmpresa() {
        const a = opsAccAsignacion(); if (!a || !opsAccCfg) return null;
        const r = opsAccCfg.roles[a.rol] || {};
        return a.filtroEmpresa || r.filtroEmpresa || null;
    }
    function opsFolioDeEmpresa(f, empresa) { try { return opsEmpresaDoc(opsEmpresaNombreFolio(f)) === opsEmpresaDoc(empresa); } catch (e) { return false; } }
    function opsAccTiene(seccion, accion) {
        const a = opsAccAsignacion();
        if (!a) return null; // null = admin del portal o matriz sin cargar → decide la regla anterior
        const rol = opsAccCfg.roles[a.rol];
        // Solo lectura (de la persona o del rol entero): ve todo lo que su rol permite ver, no cambia nada.
        if ((a.soloLectura || rol.soloLectura) && !["ver", "contacto", "dinero"].includes(accion)) return false;
        const m = (rol.matriz || {})[opsAccSeccion(seccion)] || [];
        return m.includes(accion);
    }
    function opsAccPuedeVer(seccion) {
        const r = opsAccTiene(seccion, "ver");
        return r === null ? true : r;
    }
    function opsAccVerContacto(seccion) {
        if (opsAccEsAdminPortal()) return true;
        const r = opsAccTiene(seccion || tabActual, "contacto");
        if (r !== null) return r;
        // Matriz sin cargar todavía: lo ve quien ya podía editar (regla anterior)
        return opsPuedeHacerLegado("gestionar_herramientas") || opsPuedeHacerLegado("admin_operaciones");
    }
    // Dinero (precio, costo, utilidad, comisiones): lista "Ver dinero" O casilla del rol.
    function opsAccVerDinero(seccion) {
        const lista = (opsAccCfg ? opsAccCfg.dinero : OPS_ACC_DINERO_SEED).map(x => String(x).toLowerCase().trim());
        if (lista.includes(opsAccCorreo())) return true;
        return opsAccTiene(seccion || tabActual, "dinero") === true;
    }
    function opsAccNombreRol() {
        const a = opsAccAsignacion();
        if (!a) return null;
        const r = opsAccCfg.roles[a.rol];
        return r.nombre + (a.soloLectura || r.soloLectura ? " · Solo lectura" : "") + (a.sugerido ? " (sin rol fijo)" : "");
    }

    // Traduce los permisos que ya usa el código a la matriz, según la sección abierta.
    function opsPuedeHacer(accion) {
        const a = opsAccAsignacion();
        if (!a) return opsPuedeHacerLegado(accion);
        if (accion === "consulta") return true;
        if (accion === "admin_operaciones") return a.rol === "administrador" && !a.soloLectura;
        if (accion === "autorizar_material") return opsAccTiene("solicitudes", "aprobar") === true;
        if (accion === "eliminar_solicitudes") return opsAccTiene("solicitudes", "eliminar") === true;
        if (accion === "consulta_propia") return true;
        // gestionar_herramientas / gestionar_tecnicos / solicitar_material → "Crear" o "Editar" de la sección abierta
        return opsAccTiene(tabActual, "editar") === true || opsAccTiene(tabActual, "crear") === true;
    }
    // Alias de compatibilidad con el código ya escrito en este archivo.
    function opsPuedeGestionar() {
        return opsPuedeHacer("gestionar_herramientas");
    }
    // Botones de ALTA (Nuevo servicio, Nuevo folio, Nuevo cliente…): casilla "Crear" de la sección.
    function opsPuedeCrear(seccion) {
        const a = opsAccAsignacion();
        if (!a) return opsPuedeGestionar();
        return opsAccTiene(seccion || tabActual, "crear") === true;
    }

    // ── Contadores atómicos para folios permanentes ──────────────────
    // Folio por almacén (23-oct-2026, Glen): cada almacén tiene su propia serie de folios.
    // Almacén General = HT-000001…; las ubicaciones físicas usan las iniciales de su nombre
    // (ej. Transformación Digital y Mercadotecnia = TDM-000001) o el prefijo guardado en el almacén.
    function opsPrefijoAlmacen(almacenId) {
        if (!almacenId) return "HT";
        const a = cacheAlmacenes.find(x => x.id === almacenId);
        if (!a) return "HT";
        if (a.prefijoFolio) return String(a.prefijoFolio).toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 5) || "HT";
        const palabras = String(a.nombre || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase().replace(/\(.*?\)/g, " ").split(/[^A-Z0-9]+/)
            .filter(w => w && !["Y", "DE", "DEL", "LA", "LAS", "EL", "LOS", "E"].includes(w));
        let pref = palabras.slice(0, 3).map(w => /^\d+$/.test(w) ? w : w[0]).join("") || "AL";
        if (pref === "HT") pref = "HT" + (palabras[2] ? palabras[2][0] : "1");
        // Que no choque con el prefijo de otro almacén
        const otros = cacheAlmacenes.filter(x => x.id !== almacenId && x.tipo === "ubicacion").map(x => x.prefijoFolio || null).filter(Boolean);
        let final = pref, n = 2; while (otros.includes(final)) final = pref + (n++);
        return final;
    }
    async function opsSiguienteFolioHerramienta(almacenId) {
        // Contador atómico en Supabase (ops_contadores), uno por almacén. "minimo" = el folio más alto que
        // ya existe con ese prefijo, para que nunca se repita aunque el contador se haya quedado atrás.
        const pref = opsPrefijoAlmacen(almacenId);
        const sb = await opsSb();
        const rx = new RegExp("^" + pref + "-(\\d+)$");
        const maxLocal = cacheHerr.reduce((m, h) => { const r = rx.exec(h.folio || h.id || ""); return r ? Math.max(m, Number(r[1])) : m; }, 0);
        const contador = pref === "HT" ? "herramientas" : "herramientas_" + pref;
        for (let intento = 0; intento < 5; intento++) {
            const { data, error } = await sb.rpc("ops_siguiente_contador_min", { nombre_contador: contador, minimo: maxLocal });
            if (error) throw new Error("Supabase (folio): " + error.message);
            const folio = pref + "-" + String(data).padStart(6, "0");
            if (!cacheHerr.some(h => h.id === folio)) return folio;
        }
        throw new Error("No se pudo generar un folio " + pref + " libre.");
    }
    // Folio consecutivo de Solicitud de Material: "OPERACIONES 0001", "OPERACIONES 0002"...
    // OJO: el kiosco público (solicitud-material.html) escribe con auth ANÓNIMA a Firestore,
    // por lo que NO puede compartir un contador atómico (ops_contadores) protegido para
    // usuarios autenticados — no sabemos si las reglas se lo permitirían. En vez de eso,
    // ambos puntos de entrada (kiosco y este módulo) calculan el folio leyendo el máximo
    // "folioNum" ya existente en `surtidos` con folioPrefijo:"OPERACIONES" y sumando 1.
    // Es "best effort" (no 100% atómico): si dos personas envían una solicitud en el mismo
    // instante podría repetirse un folio, igual que el resto de folios de este portal
    // (ver duplicado en almacen-pdf.js). Riesgo aceptado dado el volumen real de solicitudes.
    async function opsSiguienteFolioMaterial() {
        try {
            // Mismo puente que ya usan Ventas y Almacén — antes esto contaba folios
            // directo en Firestore, en una colección que Almacén ya no lee desde que
            // `surtidos` vive en Supabase. Corregido sep-2026 (mismo bug que en Flotilla).
            const siguiente = await window.tcSbSiguienteFolioMaterial("OPERACIONES");
            return { folio: "OPERACIONES " + String(siguiente).padStart(4, "0"), folioNum: siguiente, folioPrefijo: "OPERACIONES" };
        } catch (e) {
            console.warn("[operaciones.js] no se pudo calcular el folio consecutivo, se usa respaldo temporal:", e && e.message);
            const respaldo = Date.now() % 10000;
            return { folio: "OPERACIONES " + String(respaldo).padStart(4, "0") + "-R", folioNum: null, folioPrefijo: "OPERACIONES" };
        }
    }
    async function opsSiguienteNumeroTecnico() {
        const { db, fs } = await opsGetFB();
        const ref = fs.doc(db, COL_CONTADORES, "tecnicos");
        const n = await fs.runTransaction(db, async (tx) => {
            const snap = await tx.get(ref);
            const actual = snap.exists() ? (snap.data().valor || 0) : 0;
            const siguiente = actual + 1;
            tx.set(ref, { valor: siguiente }, { merge: true });
            return siguiente;
        });
        return "TEC-" + String(n).padStart(3, "0");
    }

    // ── Registrar un movimiento (nunca se edita ni se borra) ──────────
    async function opsRegistrarMovimiento(datos) {
        const mov = {
            herramientaId: datos.herramientaId,
            tecnicoAnteriorId: datos.tecnicoAnteriorId || null,
            tecnicoNuevoId: datos.tecnicoNuevoId || null,
            // Mismo dato que tecnicoAnterior/NuevoId, en vocabulario de almacenes
            // ("traspaso entre almacenes") — listo para el puente con Aspel sin
            // tener que reconstruir el historial después.
            almacenOrigenId: opsAlmacenIdDe(datos.tecnicoAnteriorId),
            almacenDestinoId: opsAlmacenIdDe(datos.tecnicoNuevoId),
            ubicacionAnterior: datos.ubicacionAnterior || null,
            ubicacionNueva: datos.ubicacionNueva || null,
            tipo: datos.tipo,
            motivo: datos.motivo || null,
            observaciones: datos.observaciones || null,
            usuarioEmail: opsUsuarioActual(),
            usuarioNombre: opsNombreActual(),
            fecha: opsFechaHora(),
        };
        const sb = await opsSb();
        const fila = {};
        Object.keys(mov).forEach(k => { fila[opsSnake(k)] = mov[k] === undefined ? null : mov[k]; });
        const { error } = await sb.from("ops_movimientos").insert(fila);
        if (error) throw new Error("Supabase (movimiento): " + error.message);
        cacheMov.unshift(mov);
        opsCopiaFirestore((db, fs) => fs.addDoc(fs.collection(db, COL_MOVIMIENTOS), mov).catch(() => {}));
    }

    // ═══════════════ RESPONSIVA PDF INDIVIDUAL (jsPDF) ═══════════════
    // Genera un PDF de una sola pieza con los datos REALES de Firestore
    // (folio HT-XXXXXX, técnico, fecha de asignación) — mismo diseño
    // azul/rojo/gris ya aprobado. Se dispara sola al confirmar una
    // asignación/transferencia, y también desde un botón manual en la
    // ficha de la herramienta mientras esté "asignada".
    const PDF_AZUL = [10, 46, 92];
    const PDF_ROJO = [192, 24, 45];
    const PDF_GRIS = [88, 89, 91];
    const PDF_GRIS_LINEA = [191, 192, 194];
    const PDF_GRIS_CLARO = [233, 233, 234];

    function opsGenerarResponsivaPDF(herramientaId, silencioso) {
        if (!window.jspdf || !window.jspdf.jsPDF) {
            console.error("[operaciones.js] jsPDF no está cargado.");
            return;
        }
        const h = cacheHerr.find(x => x.id === herramientaId);
        if (!h || !h.tecnicoActualId) return;
        const t = cacheTec.find(x => x.id === h.tecnicoActualId);
        if (!t) return;

        const { jsPDF } = window.jspdf;
        const doc = new jsPDF({ unit: "pt", format: "letter" });
        const W = 612, M = 46;
        let y;

        // Banda superior azul + filete rojo
        doc.setFillColor(...PDF_AZUL); doc.rect(0, 0, W, 68, "F");
        doc.setFillColor(...PDF_ROJO); doc.rect(0, 68, W, 3, "F");
        doc.setTextColor(255, 255, 255);
        doc.setFont("helvetica", "bold"); doc.setFontSize(15);
        doc.text("HEDMA TECNOCONTROL", M, 30);
        doc.setFont("helvetica", "normal"); doc.setFontSize(8.5);
        doc.text("S.A. DE C.V.  ·  Chihuahua, Chihuahua, México", M, 46);
        doc.setFont("helvetica", "bold"); doc.setFontSize(9);
        doc.text("Responsiva N.°: RH-" + h.folio, W - M, 27, { align: "right" });
        doc.setFont("helvetica", "normal");
        doc.text("Fecha: " + (h.fechaAsignacion || opsHoy()), W - M, 42, { align: "right" });

        y = 96;
        doc.setTextColor(...PDF_ROJO); doc.setFont("helvetica", "bold"); doc.setFontSize(15);
        doc.text("RESPONSIVA DE ASIGNACIÓN DE HERRAMIENTA", W / 2, y, { align: "center" });
        y += 16;
        doc.setTextColor(...PDF_GRIS); doc.setFont("helvetica", "normal"); doc.setFontSize(9.5);
        doc.text("Departamento de Operaciones  |  Control de Herramientas", W / 2, y, { align: "center" });

        function seccion(titulo) {
            y += 22;
            doc.setFillColor(...PDF_AZUL); doc.rect(M, y - 12, W - 2 * M, 20, "F");
            doc.setTextColor(255, 255, 255); doc.setFont("helvetica", "bold"); doc.setFontSize(10.5);
            doc.text(titulo, M + 8, y + 2);
            y += 18;
        }
        function campo(label, valor) {
            doc.setTextColor(...PDF_GRIS); doc.setFont("helvetica", "bold"); doc.setFontSize(9);
            doc.text(label, M, y);
            doc.setTextColor(20, 20, 20); doc.setFont("helvetica", "normal"); doc.setFontSize(10);
            doc.text(String(valor || "—"), M + 130, y);
            y += 16;
        }

        seccion("1  ·  DATOS DEL EMPLEADO");
        campo("Nombre completo:", t.nombre);
        campo("N.° operativo:", t.numeroOperativo);
        campo("Puesto:", t.puesto);
        campo("Departamento:", t.departamento);
        campo("Fecha de asignación:", h.fechaAsignacion || opsHoy());

        seccion("2  ·  HERRAMIENTA ASIGNADA");
        campo("Folio (permanente):", h.folio);
        campo("Descripción:", h.descripcion);
        campo("Marca / modelo:", (h.marca || "—") + " " + (h.modelo || ""));
        campo("N.° de serie:", h.numeroSerie || "—");
        campo("Ubicación:", h.ubicacionActual || "—");

        seccion("3  ·  TÉRMINOS DE LA RESPONSIVA");
        const clausulas = [
            "Recibo de conformidad la herramienta descrita arriba, en las condiciones señaladas, para uso exclusivo en mis funciones dentro de HEDMA TECNOCONTROL S.A. DE C.V.",
            "Me comprometo a dar buen uso, resguardo y mantenimiento a la herramienta, y a reportar de inmediato cualquier falla, pérdida, robo o extravío al Departamento de Operaciones.",
            "En caso de pérdida, extravío o daño por negligencia comprobada, acepto que el costo de reposición o reparación podrá ser descontado conforme a la política interna vigente.",
            "La herramienta es propiedad de HEDMA TECNOCONTROL S.A. DE C.V. y deberá devolverse íntegra al concluir la asignación o al término de la relación laboral, lo que ocurra primero.",
        ];
        doc.setDrawColor(...PDF_GRIS_LINEA); doc.setLineWidth(0.8);
        const cajaY0 = y - 4;
        doc.setTextColor(20, 20, 20); doc.setFont("helvetica", "normal"); doc.setFontSize(8.7);
        clausulas.forEach(c => {
            const lineas = doc.splitTextToSize("•  " + c, W - 2 * M - 16);
            doc.text(lineas, M + 8, y);
            y += lineas.length * 11 + 5;
        });
        doc.rect(M, cajaY0, W - 2 * M, y - cajaY0 + 4);
        doc.setFillColor(...PDF_ROJO); doc.rect(M, cajaY0, 3, y - cajaY0 + 4, "F");
        y += 26;

        seccion("4  ·  FIRMAS DE ENTREGA-RECEPCIÓN");
        y += 34;
        const colW = (W - 2 * M - 20) / 2;
        doc.setDrawColor(...PDF_GRIS_LINEA);
        doc.line(M, y, M + colW, y);
        doc.line(M + colW + 20, y, M + 2 * colW + 20, y);
        y += 12;
        doc.setTextColor(...PDF_AZUL); doc.setFont("helvetica", "bold"); doc.setFontSize(9);
        doc.text("QUIEN ENTREGA", M + colW / 2, y, { align: "center" });
        doc.text("QUIEN RECIBE", M + colW + 20 + colW / 2, y, { align: "center" });
        y += 12;
        doc.setTextColor(...PDF_GRIS); doc.setFont("helvetica", "normal"); doc.setFontSize(7.6);
        doc.text("Responsable de Operaciones / Almacén", M + colW / 2, y, { align: "center" });
        doc.text(t.nombre + " — Nombre y firma", M + colW + 20 + colW / 2, y, { align: "center" });

        doc.setTextColor(...PDF_GRIS); doc.setFontSize(7.3);
        doc.text("HEDMA TECNOCONTROL S.A. DE C.V. · Generado automáticamente desde Control de Herramientas · " + opsFechaHora().slice(0, 16).replace("T", " "), M, 770);

        const nombreArchivo = "Responsiva_" + h.folio + "_" + t.numeroOperativo + ".pdf";
        doc.save(nombreArchivo);
        if (!silencioso && window.mostrarPush) mostrarPush("Herramientas", "Responsiva PDF generada: " + nombreArchivo, ICON.file);
    }
    window.opsGenerarResponsivaPDF = opsGenerarResponsivaPDF;

    function opsNombreTecnico(idInterno) {
        if (!idInterno) return "Sin asignar";
        const t = cacheTec.find(x => x.id === idInterno);
        return t ? `${t.nombre} (${t.numeroOperativo})` : "Técnico desconocido";
    }

    // Traspaso técnico-a-técnico pendiente de aceptación para esta pieza, si hay uno.
    // Mientras exista, la pieza queda bloqueada: nadie puede iniciar otro movimiento
    // sobre ella salvo cancelar este traspaso (Almacén/Operaciones).
    function opsTraspasoPendientePara(herramientaId) {
        return cacheTraspasosPend.find(t => t.herramientaId === herramientaId) || null;
    }

    // El almacén de una pieza se DERIVA de tecnicoActualId — no es un campo aparte
    // que se pueda desincronizar. null/vacío = Almacén General.
    // Retrocompatible: si se le pasa el objeto herramienta completo, respeta su
    // almacenId explícito (piezas en una ubicación física, ej. "Banco de trabajo
    // Saltillo", sin técnico asignado) — si se le pasa solo un id de técnico
    // (como ya hacía antes en movimientos/traspasos), se comporta igual que siempre.
    function opsAlmacenIdDe(tecnicoIdOrHerramienta) {
        if (tecnicoIdOrHerramienta && typeof tecnicoIdOrHerramienta === "object") {
            return tecnicoIdOrHerramienta.tecnicoActualId || tecnicoIdOrHerramienta.almacenId || ALMACEN_GENERAL_ID;
        }
        return tecnicoIdOrHerramienta || ALMACEN_GENERAL_ID;
    }
    function opsNombreAlmacen(tecnicoId) {
        return tecnicoId ? opsNombreTecnico(tecnicoId) : "Almacén General";
    }

    // Equipo con requiereAutorizacion=true (ej. calibración TecnoLab) solo lo puede
    // mover/asignar/traspasar alguien de esta lista — configurable sin tocar código.
    function opsEsAutorizadorCalibracion() {
        const correo = opsUsuarioActual();
        return (window.esAdminTotal && window.esAdminTotal(correo)) || cacheAutorizadoresCalibracion.some(a => (a.email || "").toLowerCase() === correo);
    }

