        cacheAutorizadoresCalibracion = cacheAutorizadoresCalibracion.filter((_, i) => i !== idx);
        opsGuardarAutorizadoresCalibracion().catch(err => alert("No se pudo guardar: " + err.message));
        opsAbrirConfigCalibracion();
