                if (file) x.archivo = await opsSubirArchivo("herramientas/" + id + "/facturas", file);
                await opsHerrGuardarExtra(h, { facturas: (h.facturas || []).concat([x]) }, `Factura ${num}${x.proveedor ? " de " + x.proveedor : ""}${x.monto ? " por " + opsDinero(x.monto) : ""}`);
