                hotelId: f.hotelId || null, hotelDesayuno: !!f.hotelDesayuno, desayunosHotel: f.desayunosHotel || 0, cobroManual: !!f.cobroManual,
                gasolinaDeposito: !!f.gasolinaDeposito, casetasDeposito: !!f.casetasDeposito,
